// Global Cloudflare Workers bindings.
//
// This file is normally generated by `npm run cf-typegen` (wrangler types).
// It is committed because the backend is type-checked in CI and `wrangler`
// cannot run on the Android device this project is developed on.
//
// The shape must match backend/wrangler.toml:
//
//   [[d1_databases]]   binding = "DB"
//   [[r2_buckets]]     binding = "R2_BACKUPS"
//   [[kv_namespaces]]  binding = "SESSION_KV"
//   [[kv_namespaces]]  binding = "RATE_LIMIT_KV"
//   [durable_objects]  binding = "SYNC_COORDINATOR"
//
// Values marked `secret` are set with `wrangler secret put <NAME>` and are
// never present in wrangler.toml.

interface CloudflareBindings {
  // Bindings
  DB: D1Database;
  R2_BACKUPS: R2Bucket;
  SESSION_KV: KVNamespace;
  RATE_LIMIT_KV: KVNamespace;
  SYNC_COORDINATOR: DurableObjectNamespace;

  // Vars
  ENVIRONMENT: string;

  // Secrets
  GOOGLE_CLIENT_ID: string;
  GOOGLE_CLIENT_SECRET: string;
  JWT_SECRET: string;
  ADMIN_API_KEY: string;
  ENCRYPTION_KEY: string;
  SENTRY_DSN?: string;
}
